insert into categories (slug, name, description, how_to_choose, sort_order) values ('hosting', 'Hosting', 'Where the app''s frontend and server code run.', 'Match the runtime to the framework, check whether the free plan allows commercial use, and check what happens at the usage cap (pause or bill).', 1)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('database', 'Database', 'The primary datastore for application data.', 'Default to Postgres unless you have a reason not to. Check scale-to-zero, branching for preview environments, and whether free projects pause when idle.', 2)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('auth', 'Auth', 'Sign-up, sign-in, sessions, and organizations.', 'For B2B, organizations and enterprise SSO matter more than social logins. Check the price per SSO connection and where user records live.', 3)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('payments', 'Payments', 'Checkout, subscriptions, invoices, and tax.', 'Decide first whether you want a merchant of record (they handle sales tax and VAT for a higher fee) or to handle tax yourself on a payment processor.', 4)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('email', 'Email', 'Transactional email: invites, receipts, password resets.', 'Deliverability and domain setup (SPF, DKIM, DMARC) matter more than price at small volume. Keep marketing email on a separate stream or subdomain.', 5)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('secrets', 'Secrets', 'API keys and environment variables across environments.', 'One source of truth per environment, synced to the host. Check per-seat or per-identity pricing as the team grows.', 6)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('dns', 'DNS', 'Domain records for the app and for email authentication.', 'Pick a provider with a good API and fast propagation; the record limits on free plans rarely matter for one app.', 7)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('monitoring', 'Monitoring', 'Error tracking, uptime checks, and logs.', 'Error tracking with source maps first, uptime checks second. Check whether the free plan allows more than one user.', 8)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('analytics', 'Analytics', 'Product and web analytics.', 'B2B products need per-account (group) analytics, not just pageviews. Cookieless tools can avoid a consent banner for web stats.', 9)
insert into categories (slug, name, description, how_to_choose, sort_order) values ('storage', 'Storage', 'File and object storage for uploads and exports.', 'Watch egress (download) fees; they dominate cost for public files.', 10)
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('vercel', 'Vercel', 'hosting', 'https://vercel.com', 'https://vercel.com/pricing', 'Managed hosting for frontend frameworks with serverless functions and preview deployments.', 'First-class Next.js support with a preview URL for every branch.', '["Next.js apps","Preview deployments per pull request","Small teams that want no servers to manage"]'::jsonb, '["Hobby (free) is for personal, non-commercial use; a product that charges money needs Pro.","Hobby projects pause when they exceed the included usage; extra usage can''t be bought on Hobby."]'::jsonb, 'Hobby, $0/month: 1M function invocations, 4 hours Active CPU, 1M CDN requests, 100 GB Fast Data Transfer and 10 GB Fast Origin Transfer per month, 1 developer seat.', 'Pro: $20/month, including $20 of usage credit, then pay as you go.', false, false, false, 1, '{"nextjs":{"weight":3,"reason":"Built by the Next.js team; Next.js features work without adapters."},"low_cost":{"weight":-1,"reason":"Free only for non-commercial use; a paying product starts at $20/month."},"long_running":{"weight":-2,"reason":"Functions are request-scoped; long jobs need a queue or another host."},"edge":{"weight":1,"reason":"Global CDN with edge middleware."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('cloudflare-workers', 'Cloudflare Workers', 'hosting', 'https://workers.cloudflare.com', 'https://developers.cloudflare.com/workers/platform/pricing/', 'Serverless functions that run on Cloudflare''s edge network.', 'Very low cost at scale with no egress charges.', '["Global low-latency APIs","High request volume on a small budget","Apps already on Cloudflare"]'::jsonb, '["The Workers runtime is not full Node.js; some Node libraries and Next.js features need an adapter.","Free plan caps CPU at 10 ms per invocation."]'::jsonb, 'Workers Free: 100,000 requests per day and 10 ms of CPU time per invocation.', 'Workers Paid: $5/month minimum per account, including 10M requests and 30M CPU ms per month; then $0.30 per additional million requests.', null, false, false, 2, '{"edge":{"weight":3,"reason":"Code runs in Cloudflare''s edge locations by default."},"low_cost":{"weight":3,"reason":"100k free requests a day, then $5/month covers 10M requests, with no egress charges."},"high_volume":{"weight":2,"reason":"Per-request pricing stays low at high volume and there are no data transfer charges."},"nextjs":{"weight":-1,"reason":"Next.js runs through an adapter, not natively."},"long_running":{"weight":-2,"reason":"Invocations are CPU-time limited; use Queues or Containers for long work."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('netlify', 'Netlify', 'hosting', 'https://www.netlify.com', 'https://www.netlify.com/pricing/', 'Managed hosting for static sites and frontend frameworks with serverless functions.', 'Simple credit-based hosting with no per-seat charge on Pro.', '["Static and Jamstack sites","Astro, SvelteKit and other non-Next frameworks","Teams that want no per-seat fees"]'::jsonb, '["When monthly credits run out, the site pauses until the next billing cycle on the free plan."]'::jsonb, 'Free: 300 credits per month (a production deploy is 15 credits, bandwidth 20 credits per GB), 1 concurrent build, 1 member; the site pauses when credits run out.', 'Personal: $9/month (1,000 credits). Pro: from $20/month (3,000 credits, unlimited members).', null, false, false, 3, '{"low_cost":{"weight":1,"reason":"Paid plans start at $9/month."},"nextjs":{"weight":0,"reason":"Supports Next.js through its runtime adapter."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('render', 'Render', 'hosting', 'https://render.com', 'https://render.com/pricing', 'Managed hosting for long-running web services, workers, cron jobs and Docker containers.', 'Runs persistent servers and background workers, not just functions.', '["Long-running servers and websockets","Background workers and cron jobs","Docker-based apps"]'::jsonb, '["Render''s docs say not to use free instances for production; they spin down after 15 minutes idle.","Free Postgres expires 30 days after creation."]'::jsonb, 'Hobby workspace: free web services (512 MB RAM, 750 instance hours/month, spin down after 15 minutes idle), 5 GB bandwidth, 500 build minutes per month.', '$7/month for the smallest paid web service (512 MB RAM).', null, false, false, 4, '{"long_running":{"weight":3,"reason":"Always-on services, background workers and cron jobs are first-class."},"realtime":{"weight":2,"reason":"Persistent servers hold websocket connections."},"nextjs":{"weight":0,"reason":"Runs Next.js as a Node server."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('neon', 'Neon', 'database', 'https://neon.com', 'https://neon.com/pricing', 'Serverless Postgres with scale-to-zero and database branching.', 'Plain Postgres that scales to zero, with a branch per preview environment.', '["Postgres on serverless hosts","A database branch per pull request","Low idle cost"]'::jsonb, '["Compute scales to zero after 5 minutes idle on Free, so the first query after a pause is slower."]'::jsonb, 'Free, no card: 100 CU-hours per project, autoscaling up to 2 CU, 1 GB storage per project, 10 branches and 5 GB egress per project.', 'Launch: pay as you go, no monthly minimum: $0.106 per CU-hour and $0.35 per GB-month.', null, true, false, 1, '{"nextjs":{"weight":1,"reason":"Serverless driver works well from Vercel functions."},"low_cost":{"weight":2,"reason":"Scale-to-zero and a no-minimum paid plan keep idle cost near zero."},"regulated":{"weight":1,"reason":"SOC 2 and HIPAA (with a BAA) are listed on the Scale plan."},"per_tenant_db":{"weight":1,"reason":"Up to 100 free projects; branches and projects are cheap to create by API."},"fewer_vendors":{"weight":1,"reason":"Neon Auth adds managed auth in the same database."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('supabase', 'Supabase', 'database', 'https://supabase.com', 'https://supabase.com/pricing', 'Postgres with bundled auth, storage, realtime and an auto-generated API.', 'Postgres plus auth, storage and realtime from one vendor.', '["Fewer vendors to wire up","Realtime features","Row-level security from the client"]'::jsonb, '["Free projects pause after 1 week of inactivity.","Bundling ties auth and storage to the same vendor; moving later is more work."]'::jsonb, 'Free: 2 active projects, 500 MB database per project, 50,000 monthly active users, 5 GB egress, 1 GB file storage; pauses after 1 week inactive.', 'Pro: from $25/month, including $10/month of compute credits.', null, true, true, 2, '{"fewer_vendors":{"weight":3,"reason":"Database, auth, storage and realtime come from one dashboard."},"realtime":{"weight":3,"reason":"Built-in realtime subscriptions on Postgres changes."},"open_source":{"weight":2,"reason":"Open source and self-hostable with Docker."},"regulated":{"weight":1,"reason":"SOC 2 and ISO 27001 listed on Team; HIPAA is a paid add-on."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('turso', 'Turso', 'database', 'https://turso.tech', 'https://turso.tech/pricing', 'SQLite-compatible database built for many small databases.', 'Cheap SQLite databases, practical at one per customer.', '["A database per tenant or per user","Embedded and local-first apps","Read-heavy workloads"]'::jsonb, '["SQLite semantics, not Postgres; many ORMs and extensions differ."]'::jsonb, 'Free, no card: 100 databases, 5 GB storage, 500 million rows read and 10 million rows written per month.', 'Developer: $4.99/month (unlimited databases, 9 GB storage).', null, true, false, 3, '{"per_tenant_db":{"weight":3,"reason":"Designed for many databases; 100 are free and Developer is unlimited."},"low_cost":{"weight":2,"reason":"Generous free row limits and a $4.99/month paid plan."},"edge":{"weight":1,"reason":"Embedded replicas can serve reads close to users."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('workos-authkit', 'WorkOS AuthKit', 'auth', 'https://workos.com', 'https://workos.com/pricing', 'Hosted auth built around organizations, with enterprise SSO and directory sync as add-ons.', 'Free to 1M users, with enterprise SSO ready when a business customer asks.', '["B2B SaaS selling to companies","Enterprise SSO (SAML/OIDC) and SCIM later","Large free user allowance"]'::jsonb, '["SSO and Directory Sync are priced per connection ($125 each at 1-15); the page doesn''t state the billing period.","A custom auth domain is $99/month."]'::jsonb, 'First 1 million monthly active users free, including email and password, social login, passkeys, MFA and magic auth.', '$2,500/month per additional 1M MAU; SSO and Directory Sync from $125 per connection.', null, false, false, 3, '{"b2b":{"weight":3,"reason":"Organizations are the core model, and enterprise SSO is one switch away."},"regulated":{"weight":2,"reason":"Audit Logs and enterprise SSO are available as add-ons."},"low_cost":{"weight":2,"reason":"1M free monthly active users covers most products for a long time."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('clerk', 'Clerk', 'auth', 'https://clerk.com', 'https://clerk.com/pricing', 'Hosted auth with prebuilt UI components and organizations.', 'Fastest to a polished sign-in, with drop-in UI components.', '["Fast setup with prebuilt sign-in UI","Next.js and React apps","Consumer and prosumer apps"]'::jsonb, '["The free plan excludes MFA, passkeys and SSO.","B2B features beyond the basics (custom roles, domain restrictions) are a $100/month add-on."]'::jsonb, 'Hobby: 50,000 monthly retained users per app, 100 monthly retained organizations (up to 20 members each); no MFA, passkeys or SSO.', 'Pro: $20/month billed annually ($25 monthly), 50,000 MRU included, then $0.02 per MRU.', null, false, false, 1, '{"nextjs":{"weight":3,"reason":"First-class Next.js SDK with prebuilt components."},"b2b":{"weight":1,"reason":"Organizations on all plans; SSO and advanced B2B features cost extra."},"low_cost":{"weight":0,"reason":"50k free users, but MFA and SSO need a paid plan."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('better-auth', 'Better Auth', 'auth', 'https://better-auth.com', 'https://better-auth.com/pricing', 'Open-source TypeScript auth library that stores users in your own database.', 'Free, open source, and your users stay in your own database.', '["Owning user data with no per-user fees","Self-hosted or open-source projects","TypeScript backends"]'::jsonb, '["You run it: security updates, email delivery and session storage are your job."]'::jsonb, 'The library is free and MIT-licensed with no per-user costs. Optional managed infrastructure has a $0 Starter plan.', 'Optional infrastructure Pro: $20/month (dashboard, audit logs, security detections).', null, true, true, 2, '{"open_source":{"weight":3,"reason":"MIT-licensed library; users live in your own database."},"low_cost":{"weight":3,"reason":"No per-user fees at any scale."},"b2b":{"weight":1,"reason":"Organization and SSO plugins exist, but you operate them yourself."},"eu":{"weight":2,"reason":"User data stays in whatever region your database runs in."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('supabase-auth', 'Supabase Auth', 'auth', 'https://supabase.com/auth', 'https://supabase.com/pricing', 'Auth bundled with Supabase Postgres, with row-level security integration.', 'The natural choice when the database is already Supabase.', '["Apps already on Supabase","Row-level security keyed to the signed-in user"]'::jsonb, '["Free projects pause after a week of inactivity.","SAML SSO needs Pro; phone MFA is a $75/month add-on."]'::jsonb, 'Free: 50,000 monthly active users with social OAuth; no SAML SSO or phone MFA.', 'Pro: from $25/month, includes 100,000 MAU, then $0.00325 per MAU.', null, true, true, 4, '{"fewer_vendors":{"weight":3,"reason":"Same vendor and database as Supabase Postgres."},"open_source":{"weight":2,"reason":"Open source and self-hostable with the rest of Supabase."},"b2b":{"weight":0,"reason":"SAML SSO is available on Pro; organizations you model yourself."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('neon-auth', 'Neon Auth', 'auth', 'https://neon.com/auth', 'https://neon.com/pricing', 'Managed Better Auth that stores users and sessions in your Neon database.', 'Auth in the same Neon database, with no separate bill.', '["Apps already on Neon","Fewer vendors","Users and sessions queryable in SQL"]'::jsonb, '["Neon lists the Organization plugin as partial and MFA as coming soon.","Available in AWS regions only; above 1M MAU per project you contact Neon."]'::jsonb, 'Included in every Neon plan at no separate charge; up to 60,000 MAU per project on Free.', 'Neon Launch (pay as you go) raises the limit to 1M MAU per project.', null, true, false, 5, '{"fewer_vendors":{"weight":2,"reason":"Users live in the same Neon database, under the neon_auth schema."},"low_cost":{"weight":2,"reason":"No separate auth fee."},"b2b":{"weight":-1,"reason":"Organizations are only partly supported today."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('stripe', 'Stripe', 'payments', 'https://stripe.com', 'https://stripe.com/pricing', 'Payment processor with subscription billing, invoicing, a customer portal and tax add-ons.', 'The broadest billing toolkit and the lowest base fee; you handle tax registration.', '["Subscriptions, seats and usage-based billing","Lowest per-transaction fee","Invoices for B2B customers"]'::jsonb, '["Not a merchant of record by default: sales tax and VAT registration are yours (Stripe Tax helps calculate).","Billing adds 0.7% of billing volume on pay-as-you-go."]'::jsonb, 'No monthly fee. US cards: 2.9% + 30¢ per successful domestic transaction; +1.5% international cards; +1% when currency conversion is needed.', 'Billing: 0.7% of billing volume (pay as you go). Stripe Tax: 0.5% per transaction where you''re registered.', null, false, false, 1, '{"b2b":{"weight":3,"reason":"Invoices, seats, usage billing and a hosted customer portal."},"low_cost":{"weight":2,"reason":"Lowest base fee of the options here."},"regulated":{"weight":2,"reason":"Card data stays on Stripe, which keeps your PCI scope small."},"global_tax":{"weight":-1,"reason":"You register for and file sales tax and VAT yourself, unless you add Managed Payments (3.5% extra)."},"high_volume":{"weight":2,"reason":"Percentage fees are the lowest here and negotiable at volume."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('paddle', 'Paddle', 'payments', 'https://www.paddle.com', 'https://www.paddle.com/pricing', 'Merchant of record for software: it sells to your customer and handles tax filing.', 'Sells worldwide as merchant of record, so sales tax and VAT filing are handled for you.', '["Selling software internationally from day one","Founders who don''t want tax registrations"]'::jsonb, '["Higher fee than a plain processor (5% + 50¢).","Less control over checkout and invoices than Stripe."]'::jsonb, 'No monthly fee: 5% + 50¢ per checkout transaction.', null, null, false, false, 2, '{"global_tax":{"weight":3,"reason":"As merchant of record, Paddle collects and files sales tax and VAT."},"b2b":{"weight":1,"reason":"Subscriptions and invoices for software sales."},"low_cost":{"weight":-1,"reason":"5% + 50¢ is higher than a plain processor."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('lemon-squeezy', 'Lemon Squeezy', 'payments', 'https://www.lemonsqueezy.com', 'https://www.lemonsqueezy.com/pricing', 'Merchant of record for digital products and subscriptions, now operated alongside Stripe.', 'Merchant of record with a simple setup for digital products.', '["Digital products and small subscriptions","Solo founders selling worldwide"]'::jsonb, '["Its 2026 update says the team is building Stripe Managed Payments and plans a migration path for users; check before starting new.","Surcharges on top of 5% + 50¢: +1.5% international, +0.5% subscriptions."]'::jsonb, 'No monthly fee: 5% + 50¢ per transaction, plus listed surcharges (international, PayPal, subscriptions).', null, null, false, false, 3, '{"global_tax":{"weight":2,"reason":"Merchant of record: it files and pays tax on your behalf."},"low_cost":{"weight":-2,"reason":"Highest effective fee once surcharges apply."},"b2b":{"weight":-1,"reason":"Built for digital products more than B2B invoicing."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('resend', 'Resend', 'email', 'https://resend.com', 'https://resend.com/pricing', 'Developer-first transactional email API with React Email templates.', 'Simple API, React Email templates, and 3,000 free emails a month.', '["TypeScript and React apps","Transactional email at small to medium volume"]'::jsonb, '["Free plan caps at 100 emails a day, which a busy invite flow can hit."]'::jsonb, 'Free: 3,000 emails per month, 100 per day, 3 domains, 30-day retention, no overage.', 'Pro: $20/month for 50,000 emails ($0.90 per 1,000 overage).', null, false, false, 1, '{"nextjs":{"weight":2,"reason":"React Email templates render from the same codebase."},"low_cost":{"weight":2,"reason":"3,000 free emails a month."},"high_volume":{"weight":-1,"reason":"Per-email cost is higher than SES at large volume."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('postmark', 'Postmark', 'email', 'https://postmarkapp.com', 'https://postmarkapp.com/pricing', 'Transactional email service focused on deliverability, with separate message streams.', 'Known for transactional deliverability, with transactional and broadcast streams kept apart.', '["Mission-critical transactional email","Long activity retention for support"]'::jsonb, '["Free plan is 100 emails a month, enough for development only."]'::jsonb, 'Free developer plan: 100 emails per month, no overage, does not expire.', 'Basic: $15/month for 10,000 emails.', null, false, false, 2, '{"regulated":{"weight":2,"reason":"Activity retention up to 365 days on Pro helps audits and support."},"low_cost":{"weight":-1,"reason":"Only 100 free emails a month."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('amazon-ses', 'Amazon SES', 'email', 'https://aws.amazon.com/ses/', 'https://aws.amazon.com/ses/pricing/', 'AWS''s raw email sending service, priced per message.', 'Lowest cost per email at high volume.', '["High send volume","Teams already on AWS"]'::jsonb, '["More setup: sandbox exit request, bounce and complaint handling are yours.","No SES-specific monthly free quota is listed; new AWS accounts get general credits."]'::jsonb, 'No SES-specific free quota listed. New AWS customers get up to $200 in general Free Tier credits.', '$0.10 per 1,000 outbound emails, plus $0.12 per GB of attachments.', null, false, false, 3, '{"high_volume":{"weight":3,"reason":"$0.10 per 1,000 emails is the lowest rate here."},"low_cost":{"weight":1,"reason":"Cheapest per email once you''re sending real volume."},"nextjs":{"weight":-1,"reason":"More setup than a developer-first API."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('infisical', 'Infisical', 'secrets', 'https://infisical.com', 'https://infisical.com/pricing', 'Open-source secrets manager that syncs environment variables to hosts and CI.', 'Open source, self-hostable, with a free plan that covers a small team.', '["One source of truth for env vars across dev, preview and prod","Syncing secrets to Vercel and CI"]'::jsonb, '["Free plan has no secret versioning or rotation, and 3 environments."]'::jsonb, 'Free: 5 identities, unlimited projects, 3 environments, 10 secret syncs.', 'Pro: $20 per identity per month billed annually ($23 monthly).', null, true, true, 1, '{"open_source":{"weight":3,"reason":"MIT-licensed core; self-hosting the core is free."},"regulated":{"weight":1,"reason":"Audit logs and access controls on paid plans; self-host for full control."},"low_cost":{"weight":1,"reason":"Free for 5 identities."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('doppler', 'Doppler', 'secrets', 'https://www.doppler.com', 'https://www.doppler.com/pricing', 'Hosted secrets manager with integrations for most hosts and CI systems.', 'Polished hosted secrets sync, free for up to 3 users.', '["Teams that want a hosted service with many integrations"]'::jsonb, '["Hosted only; the pricing page doesn''t mention self-hosting."]'::jsonb, 'Developer: free for 3 users, 10 projects, 4 environments, 5 config syncs, 3 days of activity logs.', '$8/month per user beyond 3 on Developer; Team: $21/month per user.', null, false, false, 2, '{"low_cost":{"weight":1,"reason":"Free for 3 users."},"open_source":{"weight":-2,"reason":"Hosted only."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('cloudflare-dns', 'Cloudflare DNS', 'dns', 'https://www.cloudflare.com', 'https://www.cloudflare.com/plans/', 'Authoritative DNS with a CDN and DDoS protection on the free plan.', 'Free, fast DNS with a good API.', '["Most apps","Domains that also need email records (SPF, DKIM, DMARC)"]'::jsonb, '["When pointing at Vercel, set records to DNS only (grey cloud) unless you mean to proxy.","Free zones created after 2024-09-01 allow 200 records."]'::jsonb, 'Free plan includes DNS, unmetered DDoS protection and CDN; 200 DNS records per zone for new zones.', 'Pro: $25/month billed monthly ($20/month annually).', null, false, false, 1, '{"low_cost":{"weight":3,"reason":"DNS is free."},"edge":{"weight":1,"reason":"Anycast network close to users."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('amazon-route-53', 'Amazon Route 53', 'dns', 'https://aws.amazon.com/route53/', 'https://aws.amazon.com/route53/pricing/', 'AWS''s DNS service with health checks and routing policies.', 'The natural choice inside AWS, with latency and geo routing.', '["Infrastructure on AWS","Health-checked failover and geo routing"]'::jsonb, '["No free tier: billed per hosted zone and per query."]'::jsonb, null, '$0.50 per hosted zone per month (first 25), plus $0.40 per million standard queries.', null, false, false, 2, '{"long_running":{"weight":1,"reason":"Health-checked failover for always-on services."},"low_cost":{"weight":-1,"reason":"No free tier."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('sentry', 'Sentry', 'monitoring', 'https://sentry.io', 'https://sentry.io/pricing/', 'Error tracking and performance monitoring with source maps and session replay.', 'The standard for error tracking, with a free plan for one developer.', '["Error tracking with stack traces and source maps","Next.js apps (official SDK)"]'::jsonb, '["Free plan is 1 user; a team needs Team at $29/month ($26 annually)."]'::jsonb, 'Developer (free): 1 user, 5k errors, 5M spans, 50 session replays, 5 GB logs per month.', 'Team: $29/month billed monthly ($26 annually), unlimited users, 50k errors.', null, false, true, 1, '{"nextjs":{"weight":2,"reason":"Official Next.js SDK with source map upload."},"regulated":{"weight":1,"reason":"Data scrubbing controls and a self-hosted option."},"open_source":{"weight":1,"reason":"Self-hostable under the Functional Source License (Apache 2.0 after two years)."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('better-stack', 'Better Stack', 'monitoring', 'https://betterstack.com', 'https://betterstack.com/pricing', 'Uptime monitoring, status pages, on-call and log management.', 'Uptime checks and a status page, with logs in the same place.', '["Uptime monitoring and a public status page","Log search"]'::jsonb, '["The free plan is described as for personal projects."]'::jsonb, 'Free: 10 monitors and heartbeats, 1 status page, 3 GB logs per month kept 3 days.', 'Responder seat: $29/month billed yearly ($34 monthly); telemetry bundles from $25/month.', null, false, false, 2, '{"long_running":{"weight":2,"reason":"Heartbeats catch silent failures in jobs and workers."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('posthog', 'PostHog', 'analytics', 'https://posthog.com', 'https://posthog.com/pricing', 'Product analytics, session replay, feature flags and surveys in one tool.', 'Product analytics, replays and feature flags with a large free allowance.', '["Product analytics with per-account (group) analysis","Feature flags","Session replay"]'::jsonb, '["Uses cookies by default; configure persistence and consent for EU users."]'::jsonb, 'Free, no card: 1M analytics events, 5,000 session recordings, 1M feature flag requests per month, 1 project, 1 year retention.', 'Pay as you go: $0 base, billed only above each product''s free allowance.', null, true, true, 1, '{"b2b":{"weight":3,"reason":"Group analytics measures usage per customer account."},"low_cost":{"weight":2,"reason":"1M free events a month."},"open_source":{"weight":2,"reason":"MIT-licensed and self-hostable with Docker Compose."},"eu":{"weight":2,"reason":"EU cloud region available."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('plausible', 'Plausible', 'analytics', 'https://plausible.io', 'https://plausible.io/', 'Cookieless, privacy-focused web analytics hosted in the EU.', 'Simple cookieless web stats with EU hosting.', '["Marketing site traffic without a cookie banner","EU-hosted analytics"]'::jsonb, '["No free plan (30-day trial); web stats only, not product analytics."]'::jsonb, null, 'Starter: $9/month for 10k monthly pageviews (1 site); 30-day free trial.', null, true, true, 3, '{"eu":{"weight":3,"reason":"Cookieless and hosted in the EU on EU-owned infrastructure."},"open_source":{"weight":2,"reason":"AGPLv3 Community Edition is self-hostable."},"b2b":{"weight":-1,"reason":"Pageview stats, not per-account product analytics."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('vercel-web-analytics', 'Vercel Web Analytics', 'analytics', 'https://vercel.com/docs/analytics', 'https://vercel.com/docs/analytics/limits-and-pricing', 'Built-in, cookieless pageview analytics for Vercel projects.', 'One switch on a Vercel project, no cookies.', '["Quick traffic stats on a Vercel-hosted site"]'::jsonb, '["On Hobby (non-commercial), collection pauses after a 3-day grace period at 50,000 events.","No custom events on Hobby."]'::jsonb, 'Hobby: 50,000 events per month, 1-month reporting window, no custom events.', 'Pro: $0.03 per 1,000 events.', false, false, false, 2, '{"nextjs":{"weight":2,"reason":"One component in a Next.js app on Vercel."},"fewer_vendors":{"weight":2,"reason":"Part of the hosting platform you already use."},"b2b":{"weight":-1,"reason":"Web traffic only, not per-account product usage."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('cloudflare-r2', 'Cloudflare R2', 'storage', 'https://www.cloudflare.com/developer-platform/products/r2/', 'https://developers.cloudflare.com/r2/pricing/', 'S3-compatible object storage with no egress fees.', 'S3-compatible storage with no egress fees.', '["User uploads and public files","Large downloads where egress would dominate cost"]'::jsonb, '["The free tier covers Standard storage only, not Infrequent Access."]'::jsonb, 'Free each month: 10 GB-month of Standard storage, 1M Class A and 10M Class B operations.', '$0.015 per GB-month (Standard); $4.50 per million Class A operations.', null, false, false, 1, '{"low_cost":{"weight":3,"reason":"No egress fees and a 10 GB free allowance."},"high_volume":{"weight":3,"reason":"Free egress keeps download-heavy costs flat."},"edge":{"weight":1,"reason":"Served from Cloudflare''s network."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('vercel-blob', 'Vercel Blob', 'storage', 'https://vercel.com/docs/vercel-blob', 'https://vercel.com/docs/vercel-blob/usage-and-pricing', 'Object storage built into Vercel projects.', 'Zero setup on a Vercel project.', '["Small uploads on a Vercel-hosted app"]'::jsonb, '["On Hobby (non-commercial), Blob becomes unavailable for 30 days if limits are exceeded.","Paid rates are regional and include data transfer charges."]'::jsonb, 'Hobby: 1 GB storage per month, 10,000 simple and 2,000 advanced operations, 10 GB data transfer.', 'Usage-based on Pro, e.g. in iad1: $0.023/GB storage and $0.05/GB transfer.', false, false, false, 2, '{"fewer_vendors":{"weight":3,"reason":"Part of the Vercel project; no separate account."},"nextjs":{"weight":2,"reason":"SDK built for Next.js on Vercel."},"high_volume":{"weight":-1,"reason":"Data transfer is billed."}}'::jsonb, '2026-11-06')
insert into tools (slug, name, category, website, pricing_url, summary, pitch, best_for, watch_out, free_tier, paid_starts_at, free_tier_commercial_use, open_source, self_hostable, baseline, fit, verified_on) values ('amazon-s3', 'Amazon S3', 'storage', 'https://aws.amazon.com/s3/', 'https://aws.amazon.com/s3/pricing/', 'AWS''s object storage, the reference S3 API.', 'The reference object store, with the most storage classes and integrations.', '["Teams on AWS","Lifecycle rules and archival storage classes"]'::jsonb, '["Internet egress is billed beyond the first 100 GB per month across AWS."]'::jsonb, 'New AWS customers get up to $200 in Free Tier credits; the first 100 GB per month of data out to the internet is free.', null, null, false, false, 3, '{"regulated":{"weight":2,"reason":"Mature controls: object lock, encryption keys, access logs."},"long_running":{"weight":1,"reason":"Fits AWS-based backends."},"high_volume":{"weight":-1,"reason":"Egress fees grow with downloads."}}'::jsonb, '2026-11-06')
insert into recipes (slug, title, summary, body, verified_on) values ('b2b-saas', 'B2B SaaS with auth, billing and email', 'A multi-tenant web app sold to companies: organizations with roles, subscription billing per organization, and transactional email. Built on Next.js, Postgres, hosted auth and Stripe.', '{"slug":"b2b-saas","title":"B2B SaaS with auth, billing and email","summary":"A multi-tenant web app sold to companies: organizations with roles, subscription billing per organization, and transactional email. Built on Next.js, Postgres, hosted auth and Stripe.","matches":["b2b","saas","subscription","multi-tenant","multitenant","tenant","workspace","workspaces","team plan","teams","organizations","seats","dashboard for companies","business customers","fintech","crm","erp","admin portal","client portal","internal tool for companies"],"fitsWhen":["Customers are companies, and several people from one company share an account.","You charge a recurring subscription, per organization or per seat.","You need invites, roles, receipts and password-less or SSO sign-in."],"notFor":["Consumer apps with one user per account (drop the organization layer).","Marketplaces that pay out to sellers (you need Stripe Connect and a different money flow).","Apps that move or hold customer money (fintech ledgers need licensing review first)."],"stack":[{"category":"hosting","tool":"vercel","why":"Native Next.js hosting with preview deployments. Use Pro once you charge customers; Hobby is non-commercial.","alternatives":[{"tool":"render","when":"You need long-running workers or websockets in the same app."},{"tool":"cloudflare-workers","when":"Cost at very high request volume matters more than native Next.js."}]},{"category":"database","tool":"neon","why":"Plain Postgres that scales to zero, with a database branch for each preview deployment.","alternatives":[{"tool":"supabase","when":"You want database, auth and storage from one vendor."},{"tool":"turso","when":"You want a separate database per customer."}]},{"category":"auth","tool":"workos-authkit","why":"Organizations are the core model, 1M monthly users are free, and enterprise SSO is ready when a large customer asks.","alternatives":[{"tool":"clerk","when":"You want prebuilt sign-in UI fastest and don''t expect enterprise SSO soon."},{"tool":"better-auth","when":"You want users in your own database with no per-user fees, and will run it yourself."}]},{"category":"payments","tool":"stripe","why":"Subscriptions, seats, invoices and a hosted customer portal at the lowest base fee.","alternatives":[{"tool":"paddle","when":"You sell worldwide and want a merchant of record to file sales tax and VAT."}]},{"category":"email","tool":"resend","why":"Simple API with React Email templates and 3,000 free emails a month.","alternatives":[{"tool":"postmark","when":"Transactional deliverability and long retention matter most."}]},{"category":"secrets","tool":"infisical","why":"One source of truth for env vars across dev, preview and production, synced to Vercel.","alternatives":[{"tool":"doppler","when":"You prefer a hosted service with more integrations."}],"optional":true},{"category":"dns","tool":"cloudflare-dns","why":"Free DNS with a good API; holds the app and email records.","alternatives":[{"tool":"amazon-route-53","when":"Your infrastructure is on AWS."}]},{"category":"monitoring","tool":"sentry","why":"Error tracking with source maps from the official Next.js SDK.","alternatives":[{"tool":"better-stack","when":"You also want uptime checks and a public status page."}]},{"category":"analytics","tool":"posthog","why":"Group analytics shows usage per customer account, which is what B2B decisions need.","alternatives":[{"tool":"plausible","when":"You only need cookieless traffic stats for the marketing site."}],"optional":true},{"category":"storage","tool":"cloudflare-r2","why":"S3-compatible uploads and exports with no egress fees.","alternatives":[{"tool":"vercel-blob","when":"Uploads are small and you want zero setup on Vercel."}],"optional":true}],"steps":[{"title":"Scaffold the app","detail":"Start from a typed Next.js App Router project with strict TypeScript and a single env schema.","actions":["Create the app with TypeScript, ESLint and the App Router.","Add one env module that validates every variable at startup (zod), and import env only from there.","Commit a .env.example with every variable name and no values."],"commands":["npx create-next-app@latest my-saas --ts --eslint --app --src-dir","npm i zod"],"files":[{"path":"src/env.ts","contents":"import { z } from \"zod\";\n\nexport const env = z\n  .object({\n    DATABASE_URL: z.string().url(),\n    WORKOS_API_KEY: z.string().min(1),\n    WORKOS_CLIENT_ID: z.string().min(1),\n    WORKOS_COOKIE_PASSWORD: z.string().min(32),\n    STRIPE_SECRET_KEY: z.string().startsWith(\"sk_\"),\n    STRIPE_WEBHOOK_SECRET: z.string().startsWith(\"whsec_\"),\n    RESEND_API_KEY: z.string().startsWith(\"re_\"),\n    APP_URL: z.string().url(),\n  })\n  .parse(process.env);\n"}],"check":"The app boots locally and fails fast with a clear message when a variable is missing."},{"title":"Model tenancy in Postgres","detail":"Every customer is an organization. Every row that belongs to a customer carries organization_id, and every query filters by it.","actions":["Create a Neon project with a main branch for production and a dev branch for local work.","Create organizations, users, memberships (user, organization, role) and an audit_log table.","Add organization_id to every tenant-owned table, with an index, and a foreign key to organizations.","Put all tenant queries behind one data-access layer that requires an organization id, or enable Postgres row-level security keyed on it.","Use a migration tool (Drizzle Kit, Prisma Migrate or plain SQL files) and run migrations in CI, not by hand."],"files":[{"path":"db/001_tenancy.sql","contents":"create table organizations (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  auth_org_id text unique not null,      -- the auth provider''s organization id\n  stripe_customer_id text unique,\n  plan text not null default ''free'',\n  subscription_status text,              -- mirrored from Stripe webhooks\n  current_period_end timestamptz,\n  created_at timestamptz not null default now()\n);\n\ncreate table users (\n  id uuid primary key default gen_random_uuid(),\n  auth_user_id text unique not null,\n  email text not null,\n  created_at timestamptz not null default now()\n);\n\ncreate table memberships (\n  organization_id uuid not null references organizations(id) on delete cascade,\n  user_id uuid not null references users(id) on delete cascade,\n  role text not null check (role in (''owner'',''admin'',''member'')),\n  primary key (organization_id, user_id)\n);\n\ncreate table audit_log (\n  id bigserial primary key,\n  organization_id uuid not null references organizations(id) on delete cascade,\n  actor_user_id uuid references users(id),\n  action text not null,\n  details jsonb not null default ''{}'',\n  created_at timestamptz not null default now()\n);\ncreate index on audit_log (organization_id, created_at desc);\n\ncreate table stripe_events (            -- webhook idempotency\n  id text primary key,\n  type text not null,\n  processed_at timestamptz not null default now()\n);\n"}],"check":"A test that queries as organization A can never read organization B''s rows.","docs":["https://neon.com/docs/introduction/branching"]},{"title":"Add auth with organizations","detail":"Use the auth provider for sign-in and organization membership; keep your own users and memberships tables in sync for joins and permissions.","actions":["Install the AuthKit Next.js SDK and add the callback route and session middleware it documents.","On first sign-in, upsert the user and, if they have no organization, create one and make them owner.","Store the provider''s organization id on your organizations row (auth_org_id).","Build invites: an owner or admin invites by email; the invite carries the role.","Check the role on the server for every mutating action; never trust a role sent from the browser.","Leave SSO off until a customer asks; turning it on is per organization, priced per connection."],"commands":["npm i @workos-inc/authkit-nextjs"],"check":"Two users in one organization see the same data; a user in another organization sees none of it.","docs":["https://workos.com/docs/authkit","https://workos.com/docs/user-management/organizations"]},{"title":"Add subscription billing per organization","detail":"Bill the organization, not the person. Stripe is the source of truth for subscription state; your database mirrors it from webhooks.","actions":["Create Products and Prices in the Stripe dashboard (test mode first). Use per-seat quantity if you price by seat.","Create one Stripe Customer per organization and store stripe_customer_id on the organization.","Start upgrades with a Checkout Session in subscription mode, passing the organization id in metadata.","Use the Stripe customer portal for plan changes, cards and invoices instead of building those screens.","Handle webhooks in one route: verify the signature on the raw body, skip event ids already in stripe_events, then update the organization.","Handle at least checkout.session.completed, customer.subscription.created, customer.subscription.updated, customer.subscription.deleted and invoice.payment_failed.","Gate features on the organization''s mirrored plan and subscription_status on the server, never on a client flag.","Turn on Stripe Tax if you sell where you''re registered, or choose a merchant of record instead (see alternatives)."],"commands":["npm i stripe","stripe listen --forward-to localhost:3000/api/stripe/webhook"],"files":[{"path":"src/app/api/stripe/webhook/route.ts","contents":"import Stripe from \"stripe\";\nimport { env } from \"@/env\";\nimport { db } from \"@/db\";\n\nconst stripe = new Stripe(env.STRIPE_SECRET_KEY);\n\nexport async function POST(req: Request) {\n  const body = await req.text(); // raw body: required for signature checks\n  const signature = req.headers.get(\"stripe-signature\") ?? \"\";\n  let event: Stripe.Event;\n  try {\n    event = stripe.webhooks.constructEvent(body, signature, env.STRIPE_WEBHOOK_SECRET);\n  } catch {\n    return new Response(\"bad signature\", { status: 400 });\n  }\n\n  // Idempotency: Stripe retries, and events can arrive out of order.\n  const fresh = await db.recordStripeEvent(event.id, event.type);\n  if (!fresh) return new Response(\"ok\");\n\n  switch (event.type) {\n    case \"customer.subscription.created\":\n    case \"customer.subscription.updated\":\n    case \"customer.subscription.deleted\": {\n      const sub = event.data.object;\n      // Re-read from Stripe rather than trusting event order.\n      const latest = await stripe.subscriptions.retrieve(sub.id);\n      await db.syncSubscription(String(latest.customer), latest);\n      break;\n    }\n    case \"invoice.payment_failed\":\n      await db.flagPaymentFailed(String(event.data.object.customer));\n      break;\n  }\n  return new Response(\"ok\");\n}\n"}],"check":"In test mode, a checkout upgrades the organization, a cancel in the portal downgrades it, and replaying the same webhook changes nothing.","docs":["https://docs.stripe.com/billing/subscriptions/build-subscriptions","https://docs.stripe.com/webhooks","https://docs.stripe.com/customer-management"]},{"title":"Send transactional email","detail":"Send invites, payment-failed notices and account email from a verified subdomain.","actions":["Verify a sending subdomain (for example mail.yourdomain.com) in Resend and add its SPF and DKIM records in DNS.","Add a DMARC record for the root domain, starting at p=none with reporting, then tighten.","Write templates with React Email: invite, welcome, payment failed, and plan changed.","Let Stripe send receipts and invoices; don''t duplicate them.","Send from a server action or a queue, never from the browser, and log the message id against the organization."],"commands":["npm i resend @react-email/components"],"check":"An invite email lands in the inbox (not spam) for Gmail and Outlook test accounts.","docs":["https://resend.com/docs/introduction","https://resend.com/docs/dashboard/domains/introduction"]},{"title":"Manage secrets per environment","detail":"Keep one copy of each secret per environment and sync it to the host; never commit secrets.","actions":["Create development, preview and production environments in Infisical.","Use Stripe test keys in development and preview, and live keys in production only.","Sync each environment to the matching Vercel environment.","Add a pre-commit secret scan (for example gitleaks) and rotate any key that was ever committed."],"check":"A fresh clone runs with secrets pulled from Infisical and no .env file in git history.","docs":["https://infisical.com/docs/integrations/cloud/vercel"]},{"title":"Connect the domain","detail":"Point the app''s domain at the host and keep email records in the same DNS zone.","actions":["Add the domain to the Vercel project and create the records Vercel shows in Cloudflare DNS.","Set those records to DNS only (not proxied) unless you deliberately want Cloudflare''s proxy in front.","Keep the Resend SPF, DKIM and DMARC records in the same zone."],"check":"The apex and www load over HTTPS, and email authentication checks pass.","docs":["https://vercel.com/docs/domains/working-with-domains/add-a-domain"]},{"title":"Add monitoring and analytics","detail":"Know about errors before customers report them, and measure usage per customer account.","actions":["Install the Sentry Next.js SDK with the wizard and upload source maps in production builds.","Tag every Sentry event with organization id, never with email or other personal data.","Add an uptime check on a /api/health route.","Install PostHog, identify users, and set the organization as a group so usage rolls up per customer."],"commands":["npx @sentry/wizard@latest -i nextjs","npm i posthog-js"],"check":"A thrown test error appears in Sentry with a readable stack trace and the organization tag.","docs":["https://docs.sentry.io/platforms/javascript/guides/nextjs/","https://posthog.com/docs/product-analytics/group-analytics"]},{"title":"Set a security baseline","detail":"The things business customers ask about in their first security questionnaire.","actions":["Write an audit_log row for sign-ins, invites, role changes, billing changes and data exports.","Rate-limit sign-in, invite and webhook routes.","Use a least-privilege database role for the app; keep the owner role for migrations.","Confirm point-in-time restore is available on the database plan, and test a restore once.","Add a way for an owner to export and delete their organization''s data."],"check":"You can answer: who changed what, when; how to restore yesterday''s data; and how to delete a customer."},{"title":"Ship with preview environments","detail":"Every pull request gets its own deployment and database branch; production deploys from main.","actions":["Connect the Git repo to Vercel so each pull request gets a preview deployment.","Use the Neon integration or a CI step to create a database branch per preview and run migrations on it.","Move the Vercel project to Pro before the first paying customer; Hobby is non-commercial.","Switch Stripe to live mode only in the production environment."],"check":"A pull request shows a working preview with its own data, and merging deploys production.","docs":["https://neon.com/docs/guides/vercel-overview"]}],"bestPractices":["Bill the organization, not the user; seats are a quantity on the organization''s subscription.","Treat Stripe as the source of truth for billing and mirror it from webhooks; never set a plan from the client.","Make webhook handlers idempotent and re-read objects from Stripe instead of trusting event order.","Filter every tenant query by organization id in one shared layer, and test cross-tenant access.","Keep test and live keys in separate environments so a preview can never charge a real card.","Store provider ids (auth org id, Stripe customer id) on your rows so you can reconcile both ways.","Write an audit log from day one; adding it later means no history for the first customers."],"pitfalls":["Billing per user instead of per organization, then rebuilding billing when a second teammate joins.","Parsing the webhook body as JSON before verifying the signature (signature checks need the raw body).","Granting access on the Checkout redirect instead of on the webhook; redirects can be faked or skipped.","Launching a paid product on a free hosting plan that is non-commercial only.","Sending email from the root domain with no DMARC, then landing in spam."],"complianceNotes":["Keeping card entry on Stripe-hosted Checkout or Elements keeps your PCI DSS scope small; it doesn''t remove it.","Business customers often ask for SOC 2. This stack makes the evidence easier to gather, but SOC 2 is an audit of your company, not of your vendors.","If you sell to EU customers, you need a data processing agreement with each vendor that handles personal data, and a privacy policy that lists them.","Fintech products that hold, move or lend money may need licenses or a regulated partner. This recipe covers SaaS billing only, not money movement."],"verifiedOn":"2026-11-06"}'::jsonb, '2026-11-06')
